export const RECOGNITION_ART = Object.freeze({
  PLAQUE: { id: "recognition-plaque", name: "Winner's plaque", file: "recognition-plaque.svg", description: "A wooden plaque with an engraved brass winner's plate" },
  MEDAL: { id: "recognition-medal", name: "Winner's medal", file: "recognition-medal.svg", description: "A gold winner's medal on a navy ribbon" },
});

export const trophyArt = (id: string | null | undefined): TrophyArt | null => (id && TROPHY_ART[id]) || null;
